/**
 * Valida se o aluno possui progressão parcial cursada no ano em que o aluno esta cursando
 * @return boolean
 */
public function alunoPossuiProgressaoParcialNoAnoCursado() {

  $iAno        = $this->getTurma()->getCalendario()->getAnoExecucao();
  $aProgressao = $this->getAluno()->getProgressaoParcial();

  foreach ($aProgressao as $oProgressao) {

    foreach ($oProgressao->getVinculosProgressao() as $oProgressaoParcialVinculoDisciplina ) {

      if ( $oProgressaoParcialVinculoDisciplina->getAno() == $iAno  ) {
        return true;
      }
    }
  }

  return false;
}

/**
 * Valida se o aluno possui progressão parcial cursada no ano em que o aluno esta cursando
 * @return boolean
 */
public function progressaoParcialEvadidaNoAnoCursado() {

  $iAno        = $this->getTurma()->getCalendario()->getAnoExecucao();
  $aProgressao = $this->getAluno()->getProgressaoParcial();

  $aProgressoesEvadidas = array();
  foreach ($aProgressao as $oProgressao) {

    foreach ($oProgressao->getVinculosProgressao() as $oProgressaoParcialVinculoDisciplina ) {

      if ( $oProgressaoParcialVinculoDisciplina->getAno() != $iAno  ) {
        continue;
      }

      $oDiarioProgressao = new DiarioProgressaoParcial($oProgressao);
      if ( $oProgressaoParcialVinculoDisciplina->isEncerrado() && $oDiarioProgressao->isEvadido() ) {
        $aProgressoesEvadidas[] = $oDiarioProgressao;
      }

    }
  }

  return $aProgressoesEvadidas;
}

