/**
 * Remove o diariofinal de plugins.diariofinalreprovadoprogressao
 * Deve-se ser chamado ao cancelar o encerramento turma
 *
 * @throws DBException
 * @return booelan
 */
public function removerVinculoDiarioFinalComProgressaoEvadida() {

  if (!db_utils::inTransaction()) {
    throw new DBException("Sem Transação com o banco de dados ativa.");
  }

  if ( !$this->oMatricula->alunoPossuiProgressaoParcialNoAnoCursado() ) {
    return true;
  }

  foreach ($this->getDisciplinas() as $oDisciplina) {

    $oResultadoFinal = $oDisciplina->getResultadoFinal();

    $sWhere = " ed992_diariofinal = " .$oResultadoFinal->getCodigoResultadoFinal();
    $oDao   = new cl_diariofinalreprovadoprogressao();
    $oDao->excluir(null, $sWhere);
    if ( $oDao->erro_status == 0 ) {
      throw new DBException("Houve um problema ao cancelar o encerramento do aluno.");
    }
  }

  return true;
}


/**
 * Reprova o aluno sempre que o mesmo evadiu em uma progressão parcial
 */
public function reprovarAlunoPorEvasaoEmProgressaoParcial() {

  if (!db_utils::inTransaction()) {
    throw new DBException("Sem Transação com o banco de dados ativa.");
  }

  if ( !$this->oMatricula->alunoPossuiProgressaoParcialNoAnoCursado() ) {
    return true;
  }

  $this->removerVinculoDiarioFinalComProgressaoEvadida();
  $aProgressoesEvadidas = $this->oMatricula->progressaoParcialEvadidaNoAnoCursado();

  if ( count($aProgressoesEvadidas) == 0 ) {
    return true;
  }

  foreach ($this->getDisciplinas() as $oDisciplina) {

    $oResultadoFinal = $oDisciplina->getResultadoFinal();
    $oResultadoFinal->setResultadoFinal('R');

    $oDaoDiarioFinal                        = new cl_diariofinal();
    $oDaoDiarioFinal->ed74_c_resultadofinal = 'R';
    $oDaoDiarioFinal->ed74_i_codigo         = $oResultadoFinal->getCodigoResultadoFinal();
    $oDaoDiarioFinal->alterar($oResultadoFinal->getCodigoResultadoFinal());

    if ( $oDaoDiarioFinal->erro_status == 0 ) {

      $sMsg = "ALuno possui progressão parcial evadida e houve um problema ao alterar o resultado final do alunuo.";
      throw new DBException($sMsg);
    }

    foreach ($aProgressoesEvadidas as $oDiarioProgressao) {

      $oVinculoProgressao = $oDiarioProgressao->buscaVinculoRegencia();

      $oDao                                        = new cl_diariofinalreprovadoprogressao();
      $oDao->ed992_diariofinal                     = $oResultadoFinal->getCodigoResultadoFinal();
      $oDao->ed992_progressaoparcialalunomatricula = $oVinculoProgressao->getMatricula();

      $oDao->incluir(null);
      if ( $oDao->erro_status == 0 ) {
        throw new DBException("Houve um problema ao cancelar o encerramento do aluno.");
      }
    }
  }

  return true;
}



